$cat=Category::firstOrCreate(['name'=>$name],['slug'=>Str::slug($name),'description'=>'Freshly prepared '.$name,'is_active'=>true]);foreach($products as [$pname,$desc,$price,$img,$stock,$featured])Product::firstOrCreate(['name'=>$pname],['category_id'=>$cat->id,'slug'=>Str::slug($pname).'-'.Str::lower(Str::random(4)),'description'=>$desc,'price'=>$price,'image_url'=>$img,'stock'=>$stock,'is_available'=>true,'is_featured'=>$featured]);}} }
